WITH s AS ( SELECT normalize(BTRIM(team), NFKC) AS team_key, MAX(team) AS team, COUNT(*)::INTEGER AS games, COUNT(*) FILTER (WHERE result = 'W')::INTEGER AS win, COUNT(*) FILTER (WHERE result = 'D')::INTEGER AS draw, COUNT(*) FILTER (WHERE result = 'L')::INTEGER AS lose, COALESCE(SUM(points), 0)::INTEGER AS points, COALESCE(SUM(goals_for), 0)::INTEGER AS goals_for, COALESCE(SUM(goals_against), 0)::INTEGER AS goals_against, (ARRAY_AGG(result::text ORDER BY round_no DESC, match_time DESC NULLS LAST))[1:5] AS form, (ARRAY_AGG(team_rank ORDER BY round_no DESC, match_time DESC NULLS LAST) FILTER (WHERE team_rank IS NOT NULL))[1] AS site_rank FROM (WITH y AS ( SELECT BTRIM(d.home_team_name) AS home_team_name, BTRIM(d.away_team_name) AS away_team_name,        BTRIM(d.times) AS times, d.record_time, NULLIF(BTRIM(d.match_id), '') AS match_id,        CAST(d.home_rank AS text) AS home_rank, CAST(d.away_rank AS text) AS away_rank,        CASE WHEN BTRIM(d.home_score) ~ '^[0-9]+$' THEN BTRIM(d.home_score)::INTEGER END AS hs,        CASE WHEN BTRIM(d.away_score) ~ '^[0-9]+$' THEN BTRIM(d.away_score)::INTEGER END AS aws,        NULLIF(SUBSTRING(d.seq_key FROM '([0-9]+)$'), '')::BIGINT AS seq_no,        NULLIF(SUBSTRING(normalize(d.data_category, NFKC) FROM 'ラウンド\s*([0-9]+)'), '')::INTEGER AS round_no,        BTRIM(split_part(d.data_category, ':', 1)) AS country,        BTRIM(split_part(split_part(d.data_category, ':', 2), ' - ', 1)) AS league,        (COALESCE(d.times, '') LIKE '%ペナルティ%') AS pk FROM static_data d WHERE d.record_time >= CURRENT_TIMESTAMP - INTERVAL '300 days'   AND normalize(BTRIM(split_part(d.data_category, ':', 1)), NFKC) = normalize(BTRIM(CAST('日本' AS text)), NFKC)   AND normalize(BTRIM(split_part(split_part(d.data_category, ':', 2), ' - ', 1)), NFKC) = normalize(BTRIM(CAST('J2 リーグ' AS text)), NFKC)   AND COALESCE(BTRIM(d.goal_time), '') <> '取得エラー'   AND COALESCE(BTRIM(d.goal_team_member), '') <> '取得エラー'), st AS ( SELECT COALESCE(MAX(record_time) FILTER (WHERE round_no = 1) - INTERVAL '14 days',                 CURRENT_TIMESTAMP - INTERVAL '300 days') AS from_time FROM y), z AS ( SELECT y.*, COALESCE(y.match_id, normalize(BTRIM(y.home_team_name), NFKC) || '|' || normalize(BTRIM(y.away_team_name), NFKC)          || '|' || COALESCE(y.round_no::text, '')) AS mk FROM y, st WHERE y.record_time >= st.from_time), g AS ( SELECT mk, MAX(round_no) AS round_no, MAX(country) AS country, MAX(league) AS league, MAX(match_id) AS match_id,  (ARRAY_AGG(home_team_name ORDER BY seq_no DESC NULLS LAST, record_time DESC) FILTER (WHERE NOT pk))[1] AS home,  (ARRAY_AGG(away_team_name ORDER BY seq_no DESC NULLS LAST, record_time DESC) FILTER (WHERE NOT pk))[1] AS away,  (ARRAY_AGG(hs ORDER BY seq_no DESC NULLS LAST, record_time DESC) FILTER (WHERE NOT pk AND hs IS NOT NULL AND aws IS NOT NULL))[1] AS fh,  (ARRAY_AGG(aws ORDER BY seq_no DESC NULLS LAST, record_time DESC) FILTER (WHERE NOT pk AND hs IS NOT NULL AND aws IS NOT NULL))[1] AS fa,  (ARRAY_AGG(hs ORDER BY seq_no NULLS LAST, record_time) FILTER (WHERE NOT pk AND times IN ('ハーフタイム', '第一ハーフ') AND hs IS NOT NULL AND aws IS NOT NULL))[1] AS hh,  (ARRAY_AGG(aws ORDER BY seq_no NULLS LAST, record_time) FILTER (WHERE NOT pk AND times IN ('ハーフタイム', '第一ハーフ') AND hs IS NOT NULL AND aws IS NOT NULL))[1] AS hta,  (ARRAY_AGG(hs ORDER BY seq_no NULLS LAST, record_time) FILTER (WHERE NOT pk AND hs + aws > 0))[1] AS f1h,  (ARRAY_AGG(aws ORDER BY seq_no NULLS LAST, record_time) FILTER (WHERE NOT pk AND hs + aws > 0))[1] AS f1a,  BOOL_OR(hs > aws) FILTER (WHERE NOT pk) AS home_led,  BOOL_OR(aws > hs) FILTER (WHERE NOT pk) AS away_led,  COUNT(*) FILTER (WHERE NOT pk) AS n_regular,  (ARRAY_AGG(record_time ORDER BY seq_no DESC NULLS LAST, record_time DESC) FILTER (WHERE NOT pk))[1] AS match_time,  (ARRAY_AGG(home_rank ORDER BY seq_no DESC NULLS LAST, record_time DESC) FILTER (WHERE NOT pk))[1] AS home_rank,  (ARRAY_AGG(away_rank ORDER BY seq_no DESC NULLS LAST, record_time DESC) FILTER (WHERE NOT pk))[1] AS away_rank,  (ARRAY_AGG(hs ORDER BY seq_no DESC NULLS LAST, record_time DESC) FILTER (WHERE pk AND hs IS NOT NULL AND aws IS NOT NULL))[1] AS ph,  (ARRAY_AGG(aws ORDER BY seq_no DESC NULLS LAST, record_time DESC) FILTER (WHERE pk AND hs IS NOT NULL AND aws IS NOT NULL))[1] AS pa FROM z WHERE mk IN (SELECT mk FROM z WHERE times = '終了済' OR pk) GROUP BY mk), gg AS ( SELECT g.*, (hh IS NOT NULL AND hta IS NOT NULL AND hh <= fh AND hta <= fa) AS ht_ok FROM g WHERE fh IS NOT NULL AND fa IS NOT NULL AND home IS NOT NULL AND away IS NOT NULL) SELECT 'STATIC'::text AS season, country, league, home AS team, away AS opponent, 'H'::text AS ha, match_id, round_no, NULL::text AS phase, match_time, fh AS goals_for, fa AS goals_against, CASE WHEN fh > fa THEN 'W' WHEN fh < fa THEN 'L' ELSE 'D' END AS result, CASE WHEN fh > fa THEN 3 WHEN fh < fa THEN 0 ELSE 1 END AS points, CASE WHEN ht_ok THEN hh END AS goals_for_1st, CASE WHEN ht_ok THEN fh - hh END AS goals_for_2nd, CASE WHEN ht_ok THEN hta END AS goals_against_1st, CASE WHEN ht_ok THEN fa - hta END AS goals_against_2nd, CASE WHEN fh = 0 AND fa = 0 THEN 'N'      WHEN f1h IS NULL THEN 'U'      WHEN f1h > 0 AND f1a = 0 THEN 'T'      WHEN f1a > 0 AND f1h = 0 THEN 'O' ELSE 'U' END AS first_goal, (n_regular >= 2) AS flow_known, COALESCE(away_led, FALSE) AS ever_trailed, COALESCE(home_led, FALSE) AS ever_led, CASE WHEN BTRIM(home_rank) ~ '^[0-9]+$' THEN BTRIM(home_rank)::INTEGER END AS team_rank, (ph IS NOT NULL AND fh = fa) AS pk_flg, CASE WHEN fh = fa THEN ph END AS pk_goals_for, CASE WHEN fh = fa THEN pa END AS pk_goals_against FROM gg UNION ALL SELECT 'STATIC'::text AS season, country, league, away AS team, home AS opponent, 'A'::text AS ha, match_id, round_no, NULL::text AS phase, match_time, fa AS goals_for, fh AS goals_against, CASE WHEN fa > fh THEN 'W' WHEN fa < fh THEN 'L' ELSE 'D' END AS result, CASE WHEN fa > fh THEN 3 WHEN fa < fh THEN 0 ELSE 1 END AS points, CASE WHEN ht_ok THEN hta END AS goals_for_1st, CASE WHEN ht_ok THEN fa - hta END AS goals_for_2nd, CASE WHEN ht_ok THEN hh END AS goals_against_1st, CASE WHEN ht_ok THEN fh - hh END AS goals_against_2nd, CASE WHEN fa = 0 AND fh = 0 THEN 'N'      WHEN f1a IS NULL THEN 'U'      WHEN f1a > 0 AND f1h = 0 THEN 'T'      WHEN f1h > 0 AND f1a = 0 THEN 'O' ELSE 'U' END AS first_goal, (n_regular >= 2) AS flow_known, COALESCE(home_led, FALSE) AS ever_trailed, COALESCE(away_led, FALSE) AS ever_led, CASE WHEN BTRIM(away_rank) ~ '^[0-9]+$' THEN BTRIM(away_rank)::INTEGER END AS team_rank, (pa IS NOT NULL AND fh = fa) AS pk_flg, CASE WHEN fh = fa THEN pa END AS pk_goals_for, CASE WHEN fh = fa THEN ph END AS pk_goals_against FROM gg) som WHERE season = 'STATIC'   AND normalize(BTRIM(country), NFKC) = normalize(BTRIM(CAST('日本' AS text)), NFKC)   AND normalize(BTRIM(league), NFKC) = normalize(BTRIM(CAST('J2 リーグ' AS text)), NFKC) GROUP BY normalize(BTRIM(team), NFKC)) SELECT s.*, (s.goals_for - s.goals_against) AS goal_diff, RANK() OVER (ORDER BY s.points DESC, (s.goals_for - s.goals_against) DESC, s.goals_for DESC)::INTEGER AS rank_no FROM s ORDER BY rank_no, s.team COLLATE "ja-x-icu";
